export function getSaved(storage){try{const s=JSON.parse(storage.getItem('quqyq-360-v1'));if(!s||!Array.isArray(s.completed))return{completed:[],answers:{},read:[]};return{completed:[...new Set(s.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<6))],answers:s.answers&&typeof s.answers==='object'?s.answers:{},read:Array.isArray(s.read)?s.read.filter(n=>Number.isInteger(n)&&n>=0&&n<9):[]}}catch{return{completed:[],answers:{},read:[]}}}
